// Keeps every sheet row whose VideoUrl is still empty, checks the columns
// the template needs, and caps the batch at maxProducts. Rows with problems
// are skipped and reported — one bad row must never sink the whole catalog.
const cfg = $('Config').first().json;
const all = $input.all().map((i) => i.json);

// (No URL global in the n8n Code sandbox — a regex check does the job.)
const looksLikeUrl = (u) => /^https?:\/\/\S+$/i.test(String(u || '').trim());

// The finished VideoUrl is written back by matching the Product column (see
// "Collect video links" for why not row_number), so a product name that shows
// up twice cannot identify its own row. Count names across the WHOLE sheet —
// an already-rendered row with the same name would be matched just as well.
const nameCount = {};
for (const r of all) {
  const k = String(r.Product == null ? '' : r.Product).trim();
  if (k) nameCount[k] = (nameCount[k] || 0) + 1;
}

const rows = [];
const skipped = [];
for (const r of all) {
  if (String(r.VideoUrl || '').trim()) continue; // already has a video
  const rowNumber = r.row_number;
  const product = String(r.Product || '').trim();
  const problems = [];
  if (!product) problems.push('Product is empty');
  else if (nameCount[product] > 1)
    problems.push(
      'Product "' + product + '" appears on ' + nameCount[product] +
        ' rows — it is the key the finished VideoUrl is written back with, so it must be unique'
    );
  if (!String(r.Price || '').trim()) problems.push('Price is empty');
  if (!looksLikeUrl(r.ImageUrl1)) problems.push('ImageUrl1 is not an http(s) URL');
  if (String(r.ImageUrl2 || '').trim() && !looksLikeUrl(r.ImageUrl2)) problems.push('ImageUrl2 is not an http(s) URL');
  for (const f of ['Feature1', 'Feature2', 'Feature3']) {
    if (!String(r[f] || '').trim()) problems.push(f + ' is empty');
  }
  if (problems.length) {
    skipped.push({ rowNumber, product: product || '(no name)', problems });
    continue;
  }
  rows.push({
    rowNumber,
    Product: product,
    Price: r.Price,
    CompareAtPrice: r.CompareAtPrice,
    Feature1: r.Feature1,
    Feature2: r.Feature2,
    Feature3: r.Feature3,
    ImageUrl1: r.ImageUrl1,
    ImageUrl2: r.ImageUrl2,
    CtaText: r.CtaText,
  });
}

const max = Math.max(1, Number(cfg.maxProducts || 5));
const leftForNextRun = Math.max(0, rows.length - max);
const kept = rows.slice(0, max);

// Completed rows are expected on recurring runs. Only invalid pending rows fail.
if (!kept.length && skipped.length) {
  throw new Error(
    'No renderable rows: every row without a VideoUrl has problems. First: row ' +
      skipped[0].rowNumber + ' — ' + skipped[0].problems.join('; ')
  );
}

return [{ json: { rows: kept, skipped, leftForNextRun, totalRowsRead: all.length } }];

// Builds ONE templated Zvid project (brand knobs baked in, row data as
// {{placeholders}}) plus one { variables, name } item per catalog row —
// exactly the body POST /api/render/bulk/api-key expects. The bulk endpoint
// resolves the placeholders per item server-side.
const cfg = $('Config').first().json;
const picked = $('Rows needing videos').first().json;

const esc = (s) =>
  String(s ?? '').replace(
    /[&<>"]/g,
    (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]
  );

// Money helpers: the sheet may hold "$68", "68" or "129.50". Display keeps the
// user's own formatting (plus a currency symbol when they gave a bare number);
// math strips everything but digits and the decimal point.
const asMoneyNumber = (s) => {
  const m = String(s ?? '').replace(/[^0-9.]/g, '');
  const n = parseFloat(m);
  return Number.isFinite(n) ? n : null;
};
const formatMoney = (n, symbol) => {
  const rounded = Math.round(n * 100) / 100;
  const txt = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(2);
  return `${symbol}${txt}`;
};
const displayPrice = (raw, symbol) => {
  const t = String(raw ?? '').trim();
  if (!t) return '';
  return /^[0-9]/.test(t) ? `${symbol}${t}` : t;
};

// Auto-size long product names so they never overflow their 900px column.
const nameSizeFor = (name) => {
  const len = String(name).length;
  if (len <= 14) return 96;
  if (len <= 30) return 80;
  if (len <= 48) return 64;
  if (len <= 70) return 52;
  return 44;
};
// One feature size per row (rows sit in one list — mixed sizes look broken).
const featureSizeFor = (features) => {
  const len = Math.max(...features.map((f) => String(f).length));
  if (len <= 38) return 34;
  if (len <= 80) return 30;
  return 26;
};

const slugify = (s) =>
  String(s)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60) || 'product';

/** Templated project. Brand/config values are baked in as literals; only
 *  per-row data rides on {{placeholders}} resolved by the bulk API per item. */
function buildPayload(cfg) {
  const accent = cfg.accentColor || '#B4552D';
  const soft = cfg.accentSoft || '#E8A075';
  const cream = cfg.creamColor || '#F6EFE7';
  const ink = cfg.inkColor || '#2A1E16';
  const font = cfg.font || 'Archivo';
  const serif = cfg.serifFont || 'Fraunces';
  const heroS = Number(cfg.heroSeconds ?? 3.6);
  const featS = Number(cfg.featureSeconds ?? 4.6);
  const ctaS = Number(cfg.ctaSeconds ?? 4.2);
  const tS = Number(cfg.transitionSeconds ?? 0.55);
  const brand = esc(cfg.brandName || 'YOUR BRAND');
  const website = esc(cfg.website || 'yourstore.example');
  const kicker = esc(cfg.kicker || 'JUST DROPPED');
  const featureHeading = esc(cfg.featureHeading || "WHY YOU'LL LOVE IT");
  const dealKicker = esc(cfg.dealKicker || 'FOR A LIMITED TIME');
  const tagline = esc(cfg.tagline || 'Made for every day.');

  const rgba = (hex, a) => {
    const h = hex.replace('#', '');
    const n = parseInt(
      h.length === 3 ? h.split('').map((c) => c + c).join('') : h,
      16
    );
    return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`;
  };

  // ---- scene 1: full-bleed hero -----------------------------------------
  const heroShadeSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<defs><linearGradient id='bcShade' x1='0' y1='0' x2='0' y2='1'>` +
    `<stop offset='0' stop-color='${ink}' stop-opacity='0.5'/>` +
    `<stop offset='0.4' stop-color='${ink}' stop-opacity='0.05'/>` +
    `<stop offset='0.58' stop-color='${ink}' stop-opacity='0.45'/>` +
    `<stop offset='0.78' stop-color='${ink}' stop-opacity='0.85'/>` +
    `<stop offset='1' stop-color='${ink}' stop-opacity='0.96'/>` +
    `</linearGradient></defs>` +
    `<rect width='1080' height='1920' fill='url(#bcShade)'/>` +
    `<path d='M84 296 L84 116 L264 116' fill='none' stroke='${cream}' stroke-width='9' stroke-opacity='0.9'/>` +
    `<path d='M996 1624 L996 1804 L816 1804' fill='none' stroke='${soft}' stroke-width='9'/>` +
    `<path d='M920 240 L920 288 M896 264 L944 264' stroke='${rgba(cream, 0.75)}' stroke-width='6' stroke-linecap='round'/>` +
    `<circle cx='950' cy='1180' r='9' fill='${soft}'/>` +
    `</svg>`;

  const hero = {
    id: 'hero',
    duration: heroS,
    backgroundColor: ink,
    transition: 'smoothup',
    transitionId: 'features',
    transitionDuration: tS,
    visuals: [
      {
        type: 'IMAGE',
        src: '{{img1}}',
        width: 1080,
        height: 1920,
        position: 'center-center',
        resize: 'cover',
        zoom: true,
        track: 0,
        enterBegin: 0,
        exitEnd: heroS,
      },
      {
        type: 'SVG',
        width: 1080,
        height: 1920,
        track: 1,
        enterBegin: 0,
        exitEnd: heroS,
        svg: heroShadeSvg,
      },
      {
        type: 'TEXT',
        x: 540,
        y: 130,
        anchor: 'top-center',
        track: 2,
        enterBegin: 0.15,
        enterEnd: 0.55,
        enterAnimation: 'fade',
        exitEnd: heroS,
        style: { fontFamily: font, color: cream },
        html: `<div style='display:inline-block; border:1.5px solid ${rgba(cream, 0.55)}; border-radius:999px; padding:14px 34px; color:${cream}; font-size:26px; font-weight:800; letter-spacing:8px;'>${brand}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1330,
        width: 900,
        anchor: 'top-left',
        track: 3,
        enterBegin: 0.5,
        enterEnd: 0.95,
        enterAnimation: 'smoothup',
        exitEnd: heroS,
        style: { fontFamily: font, color: cream },
        html:
          `<div style='color:${soft}; font-size:26px; font-weight:800; letter-spacing:6px;'>${kicker}</div>` +
          `<div style='margin-top:20px; color:${cream}; font-size:{{nameSize}}px; line-height:1.06; font-weight:900; letter-spacing:-2px;'>{{product}}</div>` +
          `<div style='margin-top:26px; width:130px; height:6px; border-radius:3px; background:${soft};'></div>`,
      },
    ],
  };

  // ---- scene 2: arch product image + numbered features -------------------
  const featureBgSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<rect width='1080' height='1920' fill='${cream}'/>` +
    `<path d='M186 880 L186 524 A354 354 0 0 1 894 524 L894 880' fill='none' stroke='${accent}' stroke-width='3'/>` +
    `<path d='M120 880 L960 880' stroke='${rgba(ink, 0.22)}' stroke-width='2'/>` +
    `<circle cx='828' cy='170' r='4' fill='${rgba(accent, 0.35)}'/><circle cx='888' cy='170' r='4' fill='${rgba(accent, 0.35)}'/><circle cx='948' cy='170' r='4' fill='${rgba(accent, 0.35)}'/>` +
    `<circle cx='828' cy='230' r='4' fill='${rgba(accent, 0.35)}'/><circle cx='888' cy='230' r='4' fill='${rgba(accent, 0.35)}'/><circle cx='948' cy='230' r='4' fill='${rgba(accent, 0.35)}'/>` +
    `<path d='M96 200 q26 -34 52 0 q26 34 52 0' fill='none' stroke='${accent}' stroke-width='6' stroke-linecap='round'/>` +
    `<path d='M970 480 L970 524 M948 502 L992 502' stroke='${rgba(accent, 0.6)}' stroke-width='6' stroke-linecap='round'/>` +
    `<polygon points='120,560 160,560 140,524' fill='${soft}'/>` +
    `</svg>`;

  const featureRow = (num, varName) =>
    `<div style='margin-top:26px; border-top:1.5px solid ${rgba(ink, 0.16)}; padding-top:24px;'>` +
    `<div style='color:${accent}; font-size:24px; font-weight:800; letter-spacing:3px;'>${num}</div>` +
    `<div style='margin-top:8px; color:${ink}; font-size:{{featureSize}}px; line-height:1.32; font-weight:600;'>{{${varName}}}</div>` +
    `</div>`;

  const features = {
    id: 'features',
    duration: featS,
    backgroundColor: cream,
    transition: 'fade',
    transitionId: 'cta',
    transitionDuration: 0.5,
    visuals: [
      {
        type: 'SVG',
        width: 1080,
        height: 1920,
        track: 0,
        enterBegin: 0,
        exitEnd: featS,
        svg: featureBgSvg,
      },
      {
        // NOTE: no `resize` here on purpose — mirroring the library's
        // pro-ecom-hero-promo arch image exactly. Adding resize:"cover" to a
        // boxed top-left image makes the renderer cover the canvas from the
        // box origin instead of filling the 660x680 box (verified by render).
        type: 'IMAGE',
        src: '{{img2}}',
        x: 210,
        y: 170,
        width: 660,
        height: 680,
        anchor: 'top-left',
        zoom: true,
        radius: { tl: 330, tr: 330, bl: 0, br: 0 },
        track: 1,
        enterBegin: 0,
        enterEnd: 0.55,
        enterAnimation: 'smoothup',
        exitEnd: featS,
      },
      {
        type: 'TEXT',
        x: 830,
        y: 812,
        anchor: 'center-center',
        angle: -8,
        track: 4,
        enterBegin: 0.75,
        enterEnd: 1.1,
        enterAnimation: 'smoothup',
        exitEnd: featS,
        style: { fontFamily: font, color: cream },
        html: `<div style='display:inline-block; background:${accent}; color:${cream}; border-radius:999px; padding:16px 34px; font-size:38px; font-weight:800;'>{{price}}</div>`,
      },
      {
        type: 'TEXT',
        x: 110,
        y: 985,
        width: 860,
        anchor: 'top-left',
        track: 2,
        enterBegin: 0.45,
        enterEnd: 0.9,
        enterAnimation: 'smoothup',
        exitEnd: featS,
        style: { fontFamily: font, color: ink },
        html:
          `<div style='color:${accent}; font-size:25px; font-weight:800; letter-spacing:5px;'>${featureHeading}</div>` +
          featureRow('01', 'f1') +
          featureRow('02', 'f2') +
          featureRow('03', 'f3'),
      },
      {
        type: 'TEXT',
        x: 540,
        y: 1810,
        anchor: 'top-center',
        track: 3,
        enterBegin: 0.3,
        enterEnd: 0.7,
        enterAnimation: 'fade',
        exitEnd: featS,
        style: { fontFamily: font, color: ink },
        html: `<div style='color:${rgba(ink, 0.55)}; font-size:24px; font-weight:700; letter-spacing:6px;'>${brand} · ${website.toUpperCase()}</div>`,
      },
    ],
  };

  // ---- scene 3: price + CTA on the accent field --------------------------
  const ctaBgSvg =
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'>` +
    `<rect width='1080' height='1920' fill='${accent}'/>` +
    `<path d='M84 296 L84 116 L264 116' fill='none' stroke='${cream}' stroke-width='9' stroke-opacity='0.9'/>` +
    `<path d='M996 1624 L996 1804 L816 1804' fill='none' stroke='${cream}' stroke-width='9' stroke-opacity='0.9'/>` +
    `<path d='M120 1560 q30 -38 60 0 q30 38 60 0 q30 -38 60 0' fill='none' stroke='${rgba(cream, 0.8)}' stroke-width='7' stroke-linecap='round'/>` +
    `<path d='M170 340 L170 384 M148 362 L192 362' stroke='${rgba(cream, 0.6)}' stroke-width='6' stroke-linecap='round'/>` +
    `<circle cx='902' cy='420' r='7' fill='${rgba(cream, 0.55)}'/>` +
    `<polygon points='930,1500 970,1500 950,1464' fill='${rgba(cream, 0.7)}'/>` +
    `</svg>`;

  const priceKickerHtml = `<div style='color:${rgba(cream, 0.75)}; font-size:26px; font-weight:800; letter-spacing:6px;'>${dealKicker}</div>`;
  const bigPrice = (extra) =>
    `<div style='margin-top:24px;'><span style='color:${cream}; font-size:150px; font-weight:900; letter-spacing:-4px;'>{{price}}</span>${extra}</div>`;

  const cta = {
    id: 'cta',
    duration: ctaS,
    backgroundColor: accent,
    visuals: [
      {
        type: 'SVG',
        width: 1080,
        height: 1920,
        track: 0,
        enterBegin: 0,
        exitEnd: ctaS,
        svg: ctaBgSvg,
      },
      {
        type: 'TEXT',
        x: 540,
        y: 130,
        anchor: 'top-center',
        track: 1,
        enterBegin: 0.15,
        enterEnd: 0.5,
        enterAnimation: 'fade',
        exitEnd: ctaS,
        style: { fontFamily: font, color: cream },
        html: `<div style='color:${cream}; font-size:28px; font-weight:800; letter-spacing:10px;'>${brand}</div>`,
      },
      {
        type: 'TEXT',
        x: 90,
        y: 490,
        width: 900,
        anchor: 'top-left',
        track: 2,
        enterBegin: 0.25,
        enterEnd: 0.65,
        enterAnimation: 'smoothup',
        exitEnd: ctaS,
        style: { fontFamily: serif, color: cream },
        html: `<div style='color:${cream}; font-size:64px; line-height:1.15; font-style:italic; font-weight:500;'>${tagline}</div>`,
      },
      {
        type: 'TEXT',
        condition: '{{showCompare}}',
        x: 90,
        y: 720,
        width: 900,
        anchor: 'top-left',
        track: 3,
        enterBegin: 0.45,
        enterEnd: 0.85,
        enterAnimation: 'smoothup',
        exitEnd: ctaS,
        style: { fontFamily: font, color: cream },
        html:
          priceKickerHtml +
          bigPrice(
            `<span style='margin-left:28px; color:${rgba(cream, 0.65)}; font-size:54px; font-weight:700; text-decoration:line-through;'>{{compareAt}}</span>`
          ) +
          `<div style='margin-top:22px; display:inline-block; border:1.5px solid ${rgba(cream, 0.6)}; border-radius:999px; padding:14px 32px; color:${cream}; font-size:28px; font-weight:700;'>{{savingsLine}}</div>`,
      },
      {
        type: 'TEXT',
        condition: '{{showSingle}}',
        x: 90,
        y: 720,
        width: 900,
        anchor: 'top-left',
        track: 3,
        enterBegin: 0.45,
        enterEnd: 0.85,
        enterAnimation: 'smoothup',
        exitEnd: ctaS,
        style: { fontFamily: font, color: cream },
        html: priceKickerHtml + bigPrice(''),
      },
      {
        type: 'TEXT',
        x: 90,
        y: 1180,
        width: 900,
        anchor: 'top-left',
        track: 4,
        enterBegin: 0.65,
        enterEnd: 1.05,
        enterAnimation: 'smoothup',
        exitEnd: ctaS,
        style: { fontFamily: font, color: cream },
        html:
          `<div style='color:${rgba(cream, 0.85)}; font-size:34px; line-height:1.35; font-weight:600;'>{{product}}</div>` +
          `<div style='margin-top:36px; display:inline-block; background:${cream}; color:${ink}; border-radius:999px; padding:26px 62px; font-size:40px; font-weight:800;'>{{cta}}</div>` +
          `<div style='margin-top:24px; color:${rgba(cream, 0.7)}; font-size:26px; letter-spacing:2px; font-weight:600;'>${website}</div>`,
      },
    ],
  };

  return {
    name: 'catalog-product-video',
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: ink,
    outputFormat: 'mp4',
    // Defaults keep every placeholder resolvable even if a variable is ever
    // missing; the per-row items below always override all of them.
    variables: {
      product: 'Product name',
      nameSize: 80,
      price: '$0',
      compareAt: '',
      showCompare: false,
      showSingle: true,
      savingsLine: '',
      img1: 'https://images.pexels.com/photos/2616164/pexels-photo-2616164.jpeg?auto=compress&cs=tinysrgb&w=1620',
      img2: 'https://images.pexels.com/photos/29815561/pexels-photo-29815561.jpeg?auto=compress&cs=tinysrgb&w=1620',
      cta: 'Shop now',
      featureSize: 34,
      f1: 'Feature one',
      f2: 'Feature two',
      f3: 'Feature three',
    },
    scenes: [hero, features, cta],
    // NOTE: no `track` on the audio — the production API rejects it
    // ("audios[0].track is not allowed"), even though older library JSONs
    // carry it. src + volume is everything this design needs.
    audios: cfg.musicUrl
      ? [{ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.16) }]
      : [],
  };
}

/** One bulk item per catalog row. Values that land in HTML are escaped HERE
 *  (product names like "Fog & Field" must not break the markup). */
function buildItemVariables(cfg, row) {
  const symbol = cfg.currencySymbol || '$';
  const product = String(row.Product || '').trim();
  const features = [row.Feature1, row.Feature2, row.Feature3].map((f) =>
    String(f || '').trim()
  );
  const price = displayPrice(row.Price, symbol);
  const compareAt = displayPrice(row.CompareAtPrice, symbol);
  const priceN = asMoneyNumber(row.Price);
  const compareN = asMoneyNumber(row.CompareAtPrice);
  // Only show the strikethrough when it is an actual markdown.
  const showCompare = Boolean(
    compareAt && priceN != null && compareN != null && compareN > priceN
  );
  const savingsLine = showCompare
    ? `You save ${formatMoney(compareN - priceN, symbol)}`
    : '';
  const img1 = String(row.ImageUrl1 || '').trim();
  const img2 = String(row.ImageUrl2 || '').trim() || img1;
  const cta = String(row.CtaText || '').trim() || cfg.ctaFallback || 'Shop now';

  return {
    product: esc(product),
    nameSize: nameSizeFor(product),
    price: esc(price),
    compareAt: esc(compareAt),
    showCompare,
    showSingle: !showCompare,
    savingsLine: esc(savingsLine),
    img1,
    img2,
    cta: esc(cta),
    featureSize: featureSizeFor(features),
    f1: esc(features[0]),
    f2: esc(features[1]),
    f3: esc(features[2]),
  };
}

/** rows: [{ Product, Price, CompareAtPrice, Feature1..3, ImageUrl1, ImageUrl2,
 *  CtaText, rowNumber }] — already filtered to rows that need a video. */
function buildProject(config, rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    throw new Error('buildProject needs at least one catalog row.');
  }
  const payload = buildPayload(config);
  const items = rows.map((row, i) => ({
    variables: buildItemVariables(config, row),
    name: `${slugify(row.Product)}-r${row.rowNumber ?? i + 1}`,
  }));
  const meta = {
    products: rows.map((row, i) => ({
      index: i,
      rowNumber: row.rowNumber ?? null,
      product: String(row.Product || '').trim(),
      // The write-back key: the sheet's own Product value, untouched.
      productKey: String(row.Product == null ? '' : row.Product).trim(),
    })),
    sceneSeconds: payload.scenes.map((s) => s.duration),
    // Transitions overlap the scenes they join, so the effective length is
    // the sum minus the overlaps.
    approxVideoSeconds:
      Math.round(
        (payload.scenes.reduce((a, s) => a + s.duration, 0) -
          payload.scenes.reduce((a, s) => a + (s.transitionDuration || 0), 0)) *
          100
      ) / 100,
  };
  return { payload, items, meta };
}

const { payload, items, meta } = buildProject(cfg, picked.rows);
return [{
  json: {
    payload,
    items,
    meta: {
      ...meta,
      skipped: picked.skipped,
      leftForNextRun: picked.leftForNextRun,
      totalRowsRead: picked.totalRowsRead,
    },
  },
}];

// The free validate endpoint runs the exact resolve+validate pipeline a bulk
// item runs (first row's variables against the shared payload), so a failure
// here is a payload/data bug — surface the field list, not a generic HTTP
// error. It also returns the per-video credit price, which multiplied by the
// row count is the whole catalog's exact cost.
const res = $input.first().json;
const status = res.statusCode ?? (res.valid === true ? 200 : 400);
const body = res.body || { ...res, details: res.errors ?? res.details };

if (status !== 200) {
  const details = Array.isArray(body.details)
    ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
    : JSON.stringify(body).slice(0, 500);
  throw new Error('Zvid rejected the project (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
}

const build = $('Build project JSON').first().json;
const perVideo = Number(body.creditsRequired) || 0;
return [{
  json: {
    ...build,
    creditsPerVideo: perVideo,
    totalCredits: perVideo * build.items.length,
    warnings: body.warnings || [],
    schemaVersion: body.schemaVersion,
  },
}];

// Dry run: everything except the paid bulk submission. Read this output,
// open the editor link, then set dryRun to false in Config to go live.
const cfg = $('Config').first().json;
const d = $('Check validation').first().json;

// The draft save is best-effort (onError: continue) so a hiccup there never
// hides the quote.
let editorLink = null;
try {
  const project = $('Save draft to editor').first().json.project;
  if (project && project.id) {
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
} catch (e) { /* draft step skipped or failed */ }

return [{
  json: {
    dryRun: true,
    videosPlanned: d.items.length,
    productsToRender: d.meta.products.map((p) => 'row ' + p.rowNumber + ': ' + p.product),
    creditsPerVideo: d.creditsPerVideo,
    totalCredits: d.totalCredits,
    approxSecondsPerVideo: d.meta.approxVideoSeconds,
    rowsSkipped: d.meta.skipped,
    leftForNextRun: d.meta.leftForNextRun,
    warnings: d.warnings,
    editorLink,
    nextStep: editorLink
      ? 'Open editorLink to watch the first product video in the Zvid editor. Happy? Set dryRun to false in Config and run again — nothing is charged until then.'
      : 'Set dryRun to false in Config and run again — nothing is charged until then.',
  },
}];

// HTTP 202 means the batch is queued. Individual items can still be rejected
// at submit time (validation is best-effort per item) — map those back to
// sheet rows so the summary can name them. Job names stay NULL until a job
// completes, so results are mapped by jobId → submit index → row, never by
// name.
const res = $input.first().json;
const build = $('Check validation').first().json;

if (!res || !res.bulkId) {
  throw new Error('Bulk submit returned no bulkId: ' + JSON.stringify(res).slice(0, 400));
}

const jobIndexById = {};
for (const j of res.jobs || []) jobIndexById[j.jobId] = j.index;

const rejected = (res.errors || []).map((e) => {
  const p = build.meta.products[e.item] || {};
  return { rowNumber: p.rowNumber, product: p.product, error: e.error, details: e.details };
});

return [{
  json: {
    bulkId: res.bulkId,
    totalJobs: res.totalJobs,
    creditsReserved: res.creditsReserved,
    queueAhead: res.queueAhead,
    jobIndexById,
    rejected,
  },
}];

// Fails fast when the whole batch failed, and stops the poll loop at
// timeoutMinutes. A timeout does NOT cancel the renders — they finish on
// Zvid's side (see https://app.zvid.io); raise timeoutMinutes for bigger
// catalogs rather than re-running immediately.
const cfg = $('Config').first().json;
const poll = $input.first().json;
const b = poll.bulk || {};
const c = b.counts || {};

if (b.status === 'failed') {
  const firstError = (poll.jobs || []).map((j) => j.errorMessage).filter(Boolean)[0];
  throw new Error('Every job in bulk ' + b.id + ' failed. First error: ' + (firstError || 'no reason given'));
}

const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error(
    'Bulk ' + b.id + ' did not finish within ' + cfg.timeoutMinutes + ' minutes (' +
    (c.completed || 0) + '/' + b.totalJobs + ' done, ' + (c.pending || 0) + ' still rendering). ' +
    'The remaining renders continue on Zvid\'s side — check https://app.zvid.io before re-running, or raise timeoutMinutes.'
  );
}

return $input.all();

// Maps every finished job back to its sheet row and emits one item per
// completed video, shaped for the Google Sheets update node
// ({ Product, VideoUrl }). Failed rows keep an empty VideoUrl, so the next
// run picks them up again automatically.
//
// Why the sheet write matches on Product and NOT on row_number: the Sheets
// node re-fetches its column list every time the node is opened, and that
// list always carries row_number as `removed`. Configuring the node in the
// UI therefore drops a row_number match — n8n silently re-points "column to
// match on" at another column, the update then matches nothing, and the run
// still reports success with an empty sheet. Product is a real header column,
// so the match survives the refresh. "Rows needing videos" guarantees the
// name is unique before anything is rendered.
const poll = $input.first().json;
const sub = $('Check batch accepted').first().json;
const build = $('Check validation').first().json;
const b = poll.bulk || {};

if (b.status === 'failed') {
  const firstError = (poll.jobs || []).map((j) => j.errorMessage).filter(Boolean)[0];
  throw new Error('Every job in bulk ' + b.id + ' failed. First error: ' + (firstError || 'no reason given'));
}

const updates = [];
const failures = [];
for (const job of poll.jobs || []) {
  const index = sub.jobIndexById[job.id];
  const row = index != null ? build.meta.products[index] : null;
  if (!row) continue;
  if (job.status === 'completed' && job.outputUrl) {
    updates.push({
      // Exactly as it sits in the sheet — the lookup is a literal compare.
      Product: row.productKey == null ? row.product : row.productKey,
      VideoUrl: job.outputUrl,
      row_number: row.rowNumber,
      product: row.product,
      creditsUsed: job.creditsConsumed == null ? null : Number(job.creditsConsumed),
    });
  } else {
    failures.push({ rowNumber: row.rowNumber, product: row.product, status: job.status, error: job.errorMessage || null });
  }
}

if (!updates.length) {
  throw new Error('Bulk ' + b.id + ' finished but produced no video URLs (' + failures.length + ' job(s) failed).');
}

return updates.map((u) => ({ json: u }));

// One line per product plus the money math. Failed rows keep an empty
// VideoUrl (their credits are refunded automatically), so the next run
// retries exactly the rows that still need a video.
const poll = $('Get batch status').first().json;
const sub = $('Check batch accepted').first().json;
const build = $('Check validation').first().json;
const updates = $('Collect video links').all().map((i) => i.json);

// The sheet write is the one step that can do nothing and still look fine:
// an update that matches no row returns zero items, silently. "Write links to
// sheet" runs with alwaysOutputData so this node still executes and can say so.
const written = $('Write links to sheet').all()
  .map((i) => i.json)
  .filter((w) => w && w.VideoUrl);

if (updates.length && !written.length) {
  throw new Error(
    'Rendered ' + updates.length + ' video(s) but the sheet write matched no rows, so no VideoUrl was saved. ' +
    'Open "Write links to sheet" and set "Column to match on" back to Product — n8n re-points it at another ' +
    'column whenever the node is reconfigured. The videos themselves are fine: see sheetUpdated below for the URLs.'
  );
}

const doneRows = new Set(updates.map((u) => u.row_number));
const failures = build.meta.products
  .filter((p) => !doneRows.has(p.rowNumber))
  .map((p) => {
    const jobId = Object.keys(sub.jobIndexById).find((k) => sub.jobIndexById[k] === p.index);
    const job = (poll.jobs || []).find((j) => j.id === jobId);
    const rej = (sub.rejected || []).find((r) => r.rowNumber === p.rowNumber);
    return {
      rowNumber: p.rowNumber,
      product: p.product,
      reason: rej
        ? 'rejected at submit: ' + rej.error
        : job && job.errorMessage
          ? job.errorMessage
          : 'render did not complete',
    };
  });

const creditsSpent = (poll.jobs || []).reduce((s, j) => s + (Number(j.creditsConsumed) || 0), 0);

return [{
  json: {
    bulkId: sub.bulkId,
    bulkStatus: poll.bulk.status,
    videosDelivered: updates.length,
    videosFailed: failures.length,
    failed: failures,
    creditsSpent: creditsSpent || sub.creditsReserved,
    sheetRowsWritten: written.length,
    sheetUpdated: updates.map((u) => 'row ' + u.row_number + ': ' + u.product + ' → ' + u.VideoUrl),
    rowsSkippedBeforeSubmit: build.meta.skipped,
    leftForNextRun: build.meta.leftForNextRun,
    note: failures.length
      ? 'Failed rows keep an empty VideoUrl and are picked up again on the next run. Failed renders are refunded automatically.'
      : 'Catalog complete — every pending row now has a video.',
  },
}];

const queue = $input.first().json;
return [{ json: {
  status: 'nothing_to_render',
  message: 'All catalog rows already have a VideoUrl. No new videos were needed.',
  totalRowsRead: queue.totalRowsRead,
  videosDelivered: 0,
  creditsSpent: 0,
  nextStep: 'Add a product with an empty VideoUrl to create a new video. Clear an existing VideoUrl only when you intend to regenerate that product and spend render credits.',
} }];
